formulas.expression:
IF(
  ISBLANK( {!input_FirstName} ) ,
  'Blank First Name' ,
  IF(
    ( LEN( {!input_FirstName} ) > 40 ) ,
    LEFT( {!input_FirstName} , 40 ) ,
    {!input_FirstName}
  )
)

IF(
  ISBLANK( {!input_LastName} ) ,
  'Blank Last Name' ,
  IF(
    ( LEN( {!input_LastName} ) > 40 ) ,
    LEFT( {!input_LastName} , 40 ) ,
    {!input_LastName}
  )
)

